package de.mika.promptwerk;
import android.app.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;
/** Separate, project-based scratchpad; every edit stays local and is backed up. */
final class IdeaPad {
 final MainActivity a; final String storageKey; JSONObject notes; String active; EditText text; Spinner projects; boolean loading;
 IdeaPad(MainActivity a){this.a=a;this.storageKey=a.ideasKey();try{notes=new JSONObject(a.prefs.getString(storageKey,"{}"));}catch(Exception e){notes=new JSONObject();}if(notes.length()==0)try{notes.put("Allgemein","");}catch(Exception ignored){}active=a.prefs.getString("ideaProject","Allgemein");if(!notes.has(active))active=notes.keys().next();}
 void show(){a.ideaPadOpen=true;android.widget.LinearLayout body=a.col();body.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));body.setBackgroundColor(a.BG);body.addView(a.label("IDEEN · unabhängig vom Prompt",18,a.ACCENT));body.addView(a.label("Gedanken sammeln. Wird automatisch gesichert; mit aktiviertem Gesamtbestand auch in deinem persönlichen Drive.",13,a.MUTED));projects=new Spinner(a);body.addView(projects);text=a.input("Gedankenfetzen und spontane Ideen …");text.setGravity(android.view.Gravity.TOP);text.setInputType(1|131072|16384);text.setFilters(new InputFilter[]{new InputFilter.LengthFilter(200000)});text.setText(notes.optString(active));body.addView(text,new android.widget.LinearLayout.LayoutParams(-1,0,1));text.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!loading)try{notes.put(active,s.toString());a.prefs.edit().putString(storageKey,notes.toString()).putString("ideaProject",active).commit();DriveSync.capture(a,a.data());}catch(Exception e){a.error(e);}}public void afterTextChanged(Editable e){}});refresh();projects.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int n,long id){active=(String)p.getItemAtPosition(n);loading=true;text.setText(notes.optString(active));loading=false;a.prefs.edit().putString("ideaProject",active).apply();}});Dialog d=new Dialog(a,android.R.style.Theme_Material_NoActionBar);d.setOnDismissListener(v->{a.ideaPadOpen=false;try{DriveSync.capture(a,a.data());DriveSync.apply(a);}catch(Exception e){a.error(e);}});android.widget.LinearLayout row=a.line();a.equal(row,a.button("+ Projekt",()->{EditText name=a.input("Projektname");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});AlertDialog create=new AlertDialog.Builder(a).setTitle("Ideen für ein Projekt").setView(name).setNegativeButton("Abbrechen",null).setPositiveButton("Anlegen",null).create();create.setOnShowListener(v->create.getButton(-1).setOnClickListener(b->{String key=name.getText().toString().trim();if(key.isEmpty()||notes.has(key)){name.setError("Bitte einen neuen Projektnamen eingeben");return;}try{notes.put(key,"");active=key;a.prefs.edit().putString(storageKey,notes.toString()).putString("ideaProject",active).commit();DriveSync.capture(a,a.data());refresh();create.dismiss();}catch(Exception e){a.error(e);}}));create.show();}));a.equal(row,a.button("Leeren",()->new AlertDialog.Builder(a).setTitle("Ideen zu diesem Projekt leeren?").setMessage(active+" · Der Prompt bleibt unverändert.").setNegativeButton("Abbrechen",null).setPositiveButton("Leeren",(x,y)->text.setText("")).show()));a.equal(row,a.button("Schließen",()->d.dismiss()));body.addView(row);d.setContentView(body);d.show();d.getWindow().setLayout(-1,-1);d.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 void refresh(){ArrayList<String> names=new ArrayList<>();Iterator<String> keys=notes.keys();while(keys.hasNext())names.add(keys.next());Collections.sort(names);projects.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,names));projects.setSelection(names.indexOf(active));}
}
